const {dims,policy,score}=SourceGate;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={overview:['◫','准入总览'],supplier:['▤','供应商申报'],evidence:['◇','证据与核验'],scores:['◉','六维评分'],clarify:['☷','澄清中心'],policy:['⚙','公司评分规则'],audit:['▧','决策与审计']};
function example(id,name,category,values){return {id,name,category,region:'新加坡 / 东南亚',registration:'DEMO-'+id,contact:'Demo Representative',email:'demo@example.invalid',metrics:Object.fromEntries(dims.flatMap(d=>d.items).map((i,n)=>[i[0],values[n]])),annual:[{year:2023,ca:150,cl:100,equity:70,assets:200,ocf:18},{year:2024,ca:180,cl:120,equity:90,assets:240,ocf:21},{year:2025,ca:210,cl:140,equity:112,assets:280,ocf:25}],evidence:[],clarifications:[],log:[],authorized:false,submitted:false,signatureValid:false,signature:null,redline:'',approval:null};}
function seed(){let a=example('SG-001','Northstar Cooling Systems','冷却系统 · LLE',[6,7,65,1.5,35,3,2.5,100,3,3,3,4,96,70,4,98,95,4]);let b=example('SG-002','Meridian Power Equipment','电力设备 · LLE',[4,5,50,1.1,18,2,1.5,98,2,2,3,3,92,45,3,97,85,3]);let c=example('SG-003','Pioneer Modular Engineering','模块化工程 · EPC',[2,4,45,1,16,1,1.2,95,1,2,2,2,86,40,2,93,78,2]);b.clarifications=[{id:'C-001',dimension:'finance',question:'请补充最近三个完整财年的经审计财报，并解释经营现金流变化。',due:'2026-12-04',response:'',status:'open'}];c.redline='虚构演示：经人工确认关键质量证书造假';return {policy:policy(),selected:a.id,suppliers:[a,b,c]};}
let db;try{db=JSON.parse(localStorage.getItem('sourcegate-v1'))||seed();}catch{db=seed();}let page=location.hash.slice(1)||'overview';let signatureChecked=false;
const supplier=()=>db.suppliers.find(s=>s.id===db.selected)||db.suppliers[0];
function persist(){localStorage.setItem('sourcegate-v1',JSON.stringify(db));}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
async function digest(text){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',typeof text==='string'?new TextEncoder().encode(text):text))].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function log(action,detail=''){let s=supplier(),prev=s.log.at(-1)?.hash||'GENESIS',event={time:new Date().toISOString(),actor:'本地演示操作者',action,detail,previous:prev};event.hash=await digest(JSON.stringify(event));s.log.push(event);persist();}
function payload(s){return JSON.stringify({id:s.id,name:s.name,registration:s.registration,contact:s.contact,email:s.email,category:s.category,region:s.region,metrics:s.metrics,annual:s.annual,files:s.evidence.map(e=>({id:e.id,name:e.name,hash:e.hash,dimension:e.dimension})),policyVersion:s.signPolicy,nonce:s.nonce,signedAt:s.signedAt});}
function invalidate(){let s=supplier();s.signatureValid=false;s.authorized=false;s.approval=null;persist();}
function b64(a){return btoa(String.fromCharCode(...new Uint8Array(a)));}function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
async function sign(){let s=supplier();if(!s.name||!s.registration||!s.contact||!s.email)return toast('请先填写公司、注册号、签署人和邮箱。');if(!$('#consent')?.checked)return toast('请勾选声明确认。');try{const keys=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},true,['sign','verify']);s.signedAt=new Date().toISOString();s.nonce=crypto.randomUUID();s.signPolicy=db.policy.version;s.signature={publicKey:await crypto.subtle.exportKey('jwk',keys.publicKey),value:b64(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},keys.privateKey,new TextEncoder().encode(payload(s))))};s.signatureValid=true;s.submitted=true;s.authorized=false;s.approval=null;await log('声明签署并提交','ECDSA P-256 / SHA-256；演示密钥身份未认证');render();toast('已签署当前申报快照；仍需核实签署人身份与授权。');}catch(e){toast('当前环境无法签名，请使用 HTTPS 或 localhost。');}}
async function verify(){let s=supplier();if(!s.signature)return toast('尚未签署。');try{let k=await crypto.subtle.importKey('jwk',s.signature.publicKey,{name:'ECDSA',namedCurve:'P-256'},false,['verify']);s.signatureValid=await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},k,unb64(s.signature.value),new TextEncoder().encode(payload(s)));await log('签名完整性核验',s.signatureValid?'当前快照匹配签名':'当前快照与签名不匹配');render();toast(s.signatureValid?'密码学签名有效；身份与资料真实性仍需独立核验。':'签名验证失败，请重新签署。');}catch{s.signatureValid=false;persist();render();toast('无法验证签名。');}}
function title(k,sub,actions=''){return `<div class="page-title"><div><div class="eyebrow">SUPPLIER ASSURANCE / ${k.toUpperCase()}</div><h1>${pages[k][1]}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function selector(){return `<div class="selection"><span class="muted">当前供应商</span><select id="selected" aria-label="当前供应商">${db.suppliers.map(s=>`<option value="${s.id}" ${s.id===db.selected?'selected':''}>${esc(s.name)} · ${s.id}</option>`).join('')}</select><span class="badge">${esc(supplier().category)}</span></div>`;}
function badge(r){return `<span class="badge ${r.tone}">${r.decision}</span>`;}
function bars(r){return r.dimensions.map(d=>`<div class="bar-row"><div class="bar-meta"><span>${d.name}</span><b>${d.verified.toFixed(1)} <span class="muted">/ 100</span></b></div><div class="progress"><i style="width:${d.verified}%;background:${d.verified>=d.floor?'#278977':'#e97943'}"></i></div></div>`).join('');}
function overview(){let r=score(supplier(),db.policy);return title('overview','从供应商声明，到有据可查的准入决定。',`<button class="btn" id="new">新增供应商</button><a class="btn primary" href="#supplier">开始审核</a>`)+`<div class="grid stats"><div class="card"><div class="stat-label">准入申请</div><div class="stat-value">${db.suppliers.length.toString().padStart(2,'0')}</div><div class="stat-note">全部为虚构演示案例</div></div><div class="card"><div class="stat-label">待核验 / 草稿</div><div class="stat-value">${db.suppliers.filter(s=>/草稿|待核验/.test(score(s,db.policy).decision)).length.toString().padStart(2,'0')}</div><div class="stat-note">身份、证据与澄清独立检查</div></div><div class="card"><div class="stat-label">未关闭澄清</div><div class="stat-value">${db.suppliers.reduce((n,s)=>n+s.clarifications.filter(c=>c.status!=='closed').length,0).toString().padStart(2,'0')}</div><div class="stat-note">由审核人确认闭环</div></div><div class="card"><div class="stat-label">六维最低基准</div><div class="stat-value">60<span style="font-size:16px"> 分</span></div><div class="stat-note">默认模板 · 公司规则可配置</div></div></div><div class="grid two"><div><div class="card"><div class="section-top"><h2>供应商审核队列</h2><span class="badge">CAPEX / LLE / EPC</span></div><div class="table-wrap"><table><thead><tr><th>供应商</th><th>申报分</th><th>状态</th><th></th></tr></thead><tbody>${db.suppliers.map(s=>{let x=score(s,db.policy);return `<tr><td><span class="supplier-name" data-select="${s.id}">${esc(s.name)}</span><small>${s.id} · ${esc(s.category)}</small></td><td><span class="score-num">${x.raw.toFixed(1)}</span></td><td>${badge(x)}</td><td><button class="btn small" data-open="${s.id}">审核</button></td></tr>`;}).join('')}</tbody></table></div></div><div class="callout warn" style="margin-top:22px;margin-bottom:0">签名有效 ≠ 资料属实。文件哈希用于发现变更；真实性需要发证机构、审计报告、客户回访及人工判断。</div></div><div class="card"><h2>一条可复核的审核路径</h2><div class="flow">${[['供应商申报','六维指标、近三年财务与支持资料'],['声明签署','绑定申报快照与文件摘要'],['真实性核验','核实文件、签署人及授权'],['规则评分与澄清','按版本重算，关闭疑点'],['审批与准入','输出结论、条件及审计记录']].map((x,i)=>`<div class="flow-row"><span class="step-dot ${i===0?'done':''}">${i+1}</span><div><p>${x[0]}</p><small>${x[1]}</small></div></div>`).join('')}</div><a class="btn" href="deck.html" target="_blank" style="width:100%">查看项目说明</a></div></div><div class="grid two" style="margin-top:22px"><div class="card"><div class="section-top"><h2>当前申请 · 六维表现</h2>${badge(r)}</div>${bars(r)}<p class="hint">${esc(supplier().name)} · 核实分 ${r.verified.toFixed(1)}，申报测算分 ${r.raw.toFixed(1)}。</p></div><div class="card"><h2>本次演示可以验证什么</h2><p class="explain">实际运行：可配置计分、文件 SHA-256、浏览器电子签署、签名复核、澄清闭环、结论导出。</p><p class="explain">尚需接入：企业身份与授权认证、第三方资料核验、服务器存储、真实角色权限、ERP 供应商主数据。</p><span class="badge amber">尚不能用于正式生产准入</span></div></div>`;}
function metricField(i){return `<div class="metric-row"><label for="m-${i[0]}">${i[1]}</label><input id="m-${i[0]}" data-metric="${i[0]}" type="number" min="0" step="any" value="${supplier().metrics[i[0]]??''}"><span class="muted" style="font-size:12px">${i[3]}</span></div>`;}
function supplierView(){let s=supplier();return title('supplier','由供应商填写事实与证明，采购团队核实并决定。',`<button class="btn primary" id="save">保存申报</button>`)+selector()+`<div class="grid half"><section class="card"><h2>公司与签署人</h2><div class="fields">${[['name','公司法定名称'],['registration','公司注册号'],['category','供应品类 / 范围'],['region','服务区域'],['contact','签署人姓名'],['email','工作邮箱']].map(([k,v])=>`<div class="field"><label for="f-${k}">${v}</label><input id="f-${k}" data-field="${k}" value="${esc(s[k])}"></div>`).join('')}</div><p class="hint">本地演示无需填入真实企业秘密或个人证件。</p></section><section class="card"><h2>电子声明与签署</h2><div class="signature-box"><p class="explain">本人声明所提交资料准确、完整，并具备代表该公司提交资料的授权。资料或附件更新后须重新签署。</p><label><input type="checkbox" id="consent"> 我确认上述声明并同意签署本次快照</label><div class="actions" style="margin-top:18px"><button class="btn orange" id="sign">签署并提交</button><button class="btn" id="verify">验证当前签名</button></div></div><p class="hint">${s.signature?`签署时间 ${esc(s.signedAt)} · ${s.signatureValid?'当前签名有效':'须重新核验 / 签署'}`:'尚未签署'}</p><p class="hint">使用实际 ECDSA P-256 签名。密钥在浏览器临时生成，未绑定外部认证身份，不构成签署人真实性认证。</p></section></div><section class="card dimension" style="margin-top:22px"><h2>近三个完整财年</h2><p class="hint">默认按当前年度的前三年；可按企业财年调整。金额单位为同一币种的百万。保存后自动计算财务三项指标。</p><div class="table-wrap"><table><thead><tr>${['财年','流动资产','流动负债','权益','总资产','经营现金流'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${s.annual.map((a,n)=>`<tr>${['year','ca','cl','equity','assets','ocf'].map(k=>`<td><input aria-label="${a.year} ${k}" type="number" step="any" data-year="${n}" data-annual="${k}" value="${a[k]}" style="min-width:85px"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="grid half">${dims.map((d,n)=>`<section class="card dimension"><div class="dimension-head"><div><div class="number-token">${d.en.toUpperCase()}</div><h2>${d.name}</h2></div><span class="badge">${db.policy.weights[n]}%</span></div>${d.items.map(i=>metricField(i)+`<p class="hint">${i[5]}</p>`).join('')}<a class="btn small" href="#evidence">添加维度证明</a></section>`).join('')}</div>`;}
let fileDatabase;async function filesDB(){if(fileDatabase)return fileDatabase;return fileDatabase=await new Promise((res,rej)=>{let r=indexedDB.open('SourceGateFiles',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
async function putFile(id,file){let d=await filesDB();return new Promise((res,rej)=>{let t=d.transaction('files','readwrite');t.objectStore('files').put(file,id);t.oncomplete=res;t.onerror=()=>rej(t.error);});}async function getFile(id){let d=await filesDB();return new Promise((res,rej)=>{let r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
function evidenceView(){let s=supplier();return title('evidence','完整性、签署人身份、资料真实性分别核验。')+selector()+`<div class="callout warn">本原型不会自动声称文件真实。每个维度须有完整证据包，审核人确认其覆盖该维度所有指标；记录核验方式和出处后才计入核实分。</div><div class="grid half"><section class="card"><h2>上传维度证据包</h2><div class="field"><label for="filedim">对应维度</label><select id="filedim">${dims.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}</select></div><div class="field"><label for="file">PDF、表格或证明文件（每份 ≤ 15 MB）</label><input id="file" type="file" accept=".pdf,.csv,.xlsx,.xls,.png,.jpg,.jpeg,.txt,.json"></div><button class="btn primary" id="upload">添加并生成 SHA-256</button><p class="hint">附件内容保存在当前浏览器 IndexedDB；不会上传第三方。刷新可保留，同浏览器使用。浏览器清理将删除资料。</p></section><section class="card"><h2>签名与授权核验</h2><div class="risk-check">密码学完整性 <span style="float:right" class="badge ${s.signatureValid?'green':'amber'}">${s.signatureValid?'签名匹配':'未通过'}</span></div><div class="risk-check">身份与公司授权 <span style="float:right" class="badge ${s.authorized?'green':'amber'}">${s.authorized?'人工已核实':'待核实'}</span></div><div class="field" style="margin-top:18px"><label for="authnote">核验人、方法及授权依据</label><input id="authnote" placeholder="例如：审核人；公司登记及授权函编号" value="${esc(s.authnote||'')}"></div><div class="actions"><button class="btn" id="verify">复核签名</button><button class="btn primary" id="authorize">确认身份与授权</button></div><p class="hint">实际部署须接入受信企业身份、授权书校验及电子签平台。此处为演示人工记录。</p></section></div><section class="card" style="margin-top:22px"><div class="section-top"><h2>证据登记册</h2><span class="badge">${s.evidence.length} 份附件</span></div>${s.evidence.length?s.evidence.map(e=>`<div class="evidence-item"><div class="evidence-meta"><div><p><b>${esc(e.name)}</b></p><span class="hint">${dims.find(d=>d.id===e.dimension).name} · ${(e.size/1024).toFixed(1)} KB · ${new Date(e.time).toLocaleString('zh-CN')}</span></div><div class="actions"><span class="badge ${e.state==='verified'?'green':e.state==='rejected'?'red':'amber'}">${({pending:'待核实',verified:'已核实证据包',rejected:'不接受'})[e.state]}</span><button class="btn small" data-download="${e.id}">下载原件</button><button class="btn small" data-hashcheck="${e.id}">复核摘要</button></div></div><p class="hash">SHA-256 ${e.hash}</p><div class="review-panel"><div class="fields"><div><label>审核人</label><input aria-label="审核人 ${e.id}" id="reviewer-${e.id}" value="${esc(e.reviewer||'')}"></div><div><label>核验方式与出处</label><input aria-label="核验依据 ${e.id}" id="method-${e.id}" placeholder="发证方官网 / 审计师确认 / 回访记录" value="${esc(e.method||'')}"></div><div><label>维度证据审核结果</label><select id="state-${e.id}" aria-label="证据结果 ${e.id}">${['pending','verified','rejected'].map(t=>`<option value="${t}" ${e.state===t?'selected':''}>${({pending:'待核实',verified:'完整覆盖，予以确认',rejected:'不接受，需澄清'})[t]}</option>`).join('')}</select></div></div><button class="btn small" data-review="${e.id}">保存核验记录</button><p class="hint">${e.method?`核验记录：${esc(e.reviewer)} · ${esc(e.method)}`:'请核对文件真实性、有效期、主体、指标口径及完整覆盖。单一证书不能替代全部证据。'}</p></div></div>`).join(''):'<div class="empty">尚无附件。添加证明文件，开始建立证据链。</div>'}</section>`;}
function radar(r){let cx=180,cy=165,rad=115;let point=(n,v)=>{let a=(n*60-90)*Math.PI/180;return [cx+Math.cos(a)*rad*v,cy+Math.sin(a)*rad*v];};return `<svg class="radar" viewBox="0 0 360 335" role="img" aria-label="六维申报分与核实分雷达图">${[.2,.4,.6,.8,1].map(v=>`<polygon points="${dims.map((_,n)=>point(n,v).join(',')).join(' ')}" fill="none" stroke="#e0e8ed"/>`).join('')}${dims.map((d,n)=>`<line x1="180" y1="165" x2="${point(n,1)[0]}" y2="${point(n,1)[1]}" stroke="#e0e8ed"/><text x="${point(n,1.25)[0]}" y="${point(n,1.25)[1]}" text-anchor="middle" font-size="12" fill="#6f8393">${['市场','财务','技术','ESG','供应链','质量'][n]}</text>`).join('')}<polygon points="${r.dimensions.map((d,n)=>point(n,d.raw/100).join(',')).join(' ')}" fill="#e9794320" stroke="#e97943" stroke-width="2"/><polygon points="${r.dimensions.map((d,n)=>point(n,d.verified/100).join(',')).join(' ')}" fill="#16836625" stroke="#168366" stroke-width="2"/></svg>`;}
function scoresView(){let r=score(supplier(),db.policy);return title('scores','固定规则计算分数；证据决定哪些分数可以采信。',`<button class="btn" id="export">导出评分 JSON</button><button class="btn primary" id="print">打印审核报告</button>`)+selector()+`<div class="score-hero"><div><div class="tagline">VERIFIED SCORE</div><div class="hero-num">${r.verified.toFixed(1)} <small>/ 100</small></div><p class="subtitle">申报测算 ${r.raw.toFixed(1)} · 核实覆盖率 ${r.coverage}%</p></div><div><div class="decision">${r.decision}</div><p class="subtitle">规则版本 ${esc(db.policy.version)}</p>${r.reasons.map(t=>`<div class="reason">${esc(t)}</div>`).join('')}</div></div><div class="grid two"><div class="card"><h2>分数如何组成</h2><div class="table-wrap"><table><thead><tr><th>评估维度</th><th>权重</th><th>申报分</th><th>核实分</th><th>基准</th></tr></thead><tbody>${r.dimensions.map(d=>`<tr><td>${d.name}</td><td>${d.weight}%</td><td>${d.raw.toFixed(1)}</td><td><b>${d.verified.toFixed(1)}</b></td><td>${d.floor}</td></tr>`).join('')}</tbody></table></div><p class="hint">维度分 = Σ（子指标档位分 × 维度内权重）；总分 = Σ（维度分 × 公司维度权重）。判定使用未四舍五入值。</p></div><div class="card"><h2>六维能力分布</h2>${radar(r)}<div class="hint" style="text-align:center"><span style="color:var(--orange)">● 申报测算分</span>　<span style="color:var(--green)">● 证据核实分</span></div></div></div>${r.dimensions.map(d=>`<section class="card dimension" style="margin-top:22px"><div class="section-top"><h2>${d.name}</h2><span class="badge">${d.weight}% · 基准 ${d.floor}</span></div><div class="table-wrap"><table><thead><tr><th>指标</th><th>申报值</th><th>档位分</th><th>内部权重</th><th>证据</th></tr></thead><tbody>${d.parts.map(i=>`<tr><td>${i.name}</td><td>${i.value??'未填写'}</td><td>${i.points}</td><td>${i.weight}%</td><td><span class="badge ${i.verified?'green':'amber'}">${i.verified?'证据包已确认':'待核实'}</span></td></tr>`).join('')}</tbody></table></div></section>`).join('')}`;}
function clarifyView(){let s=supplier();return title('clarify','疑点进入任务，回复须经审核后关闭。')+selector()+`<div class="grid two"><section class="card"><h2>澄清任务</h2>${s.clarifications.length?s.clarifications.map(c=>`<div class="evidence-item"><div class="section-top"><h3>${c.id} · ${dims.find(d=>d.id===c.dimension)?.name||'综合'}</h3><span class="badge ${c.status==='closed'?'green':'amber'}">${({open:'待供应商回复',answered:'待审核关闭',closed:'已关闭'})[c.status]}</span></div><p>${esc(c.question)}</p><p class="hint">截止：${esc(c.due)}${c.status!=='closed'&&c.due<new Date().toISOString().slice(0,10)?' · 已逾期':''}</p><label for="response-${c.id}">供应商回复 / 支持资料说明</label><textarea id="response-${c.id}" ${c.status==='closed'?'disabled':''}>${esc(c.response)}</textarea><div class="actions" style="margin-top:12px"><button class="btn small" data-answer="${c.id}" ${c.status==='closed'?'disabled':''}>保存回复</button><button class="btn small primary" data-close="${c.id}" ${c.status!=='answered'?'disabled':''}>审核并关闭</button>${c.status==='closed'?`<button class="btn small" data-reopen="${c.id}">重新打开</button>`:''}</div><p class="hint">${esc(c.resolution||'评分或附件有变化时，请回到申报页更新并重新签署。关闭澄清不会自动确认附件。')}</p></div>`).join(''):'<div class="empty">暂无澄清。可添加疑问，或使用规则检查生成待补充项。</div>'}</section><section class="card"><h2>提出澄清</h2><div class="field"><label for="cdim">维度</label><select id="cdim">${dims.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}</select></div><div class="field"><label for="question">需回答的问题</label><textarea id="question" placeholder="指出数据差异、缺失证据或待验证的事实"></textarea></div><div class="field"><label for="due">截止日期</label><input type="date" id="due" value="${new Date(Date.now()+7*86400000).toISOString().slice(0,10)}"></div><div class="actions"><button class="btn primary" id="add-clarify">添加澄清</button><button class="btn" id="auto-clarify">运行规则检查</button></div><p class="hint">规则检查为缺失维度证据生成问题；未接入 AI，不会向供应商发送邮件。</p></section></div>`;}
function policyView(){let p=db.policy;return title('policy','默认 CAPEX 模板；请由采购、财务、技术和 ESG 负责人校准。',`<button class="btn primary" id="save-policy">保存新版本</button>`)+`<div class="callout warn">这是建议评分政策，尚未经公司批准。调整规则会撤销现有审批并要求按新版本重新签署。市场份额须限定可比品类，不能以企业规模替代履约能力。</div><div class="grid half"><section class="card"><h2>公司与准入门槛</h2><div class="field"><label for="company">公司 / 工作空间</label><input id="company" value="${esc(p.company)}"></div><div class="fields"><div class="field"><label for="admit">建议准入总分</label><input id="admit" type="number" min="0" max="100" value="${p.admit}"></div><div class="field"><label for="conditional">有条件准入总分</label><input id="conditional" type="number" min="0" max="100" value="${p.conditional}"></div></div><p class="hint">低于任一维度基准线：不予准入；未核验完成：待核验；已确认红线：不予准入。无自动入库操作。</p></section><section class="card"><h2>维度权重与基准线</h2><div class="policy-row muted"><span>维度</span><span>权重 %</span><span>基准分</span></div>${dims.map((d,n)=>`<div class="policy-row"><label>${d.name}</label><input aria-label="${d.name}权重" id="weight-${n}" type="number" value="${p.weights[n]}"><input aria-label="${d.name}基准" id="floor-${n}" type="number" value="${p.floors[n]}"></div>`).join('')}<p class="hint">六维权重必须合计 100%。子指标内部权重固定并在评分页显示。</p></section></div><section class="card" style="margin-top:22px"><h2>每项指标的评分锚点</h2><p class="hint">所有指标均为越高越好。低于第一档得 0 分；达到四个阈值分别得 40 / 60 / 80 / 100 分。阈值须严格递增。</p><div class="table-wrap"><table class="criteria-table"><thead><tr><th>指标与所需证据</th><th>40 分</th><th>60 分</th><th>80 分</th><th>100 分</th></tr></thead><tbody>${dims.map(d=>`<tr><th colspan="5">${d.name}</th></tr>${d.items.map(i=>`<tr><td>${i[1]} (${i[3]})<small>${i[5]}</small></td>${p.criteria[i[0]].map((v,n)=>`<td><input aria-label="${i[1]} ${[40,60,80,100][n]}分阈值" data-threshold="${i[0]}" data-index="${n}" type="number" step="any" value="${v}"></td>`).join('')}</tr>`).join('')}`).join('')}</tbody></table></div></section>`;}
function auditView(){let s=supplier(),r=score(s,db.policy);return title('audit','评分、核验、澄清与审批，汇总为可解释的准入记录。',`<button class="btn" id="export">导出完整审核 JSON</button><button class="btn" id="print">打印</button>`)+selector()+`<div class="grid two"><section class="card"><div class="section-top"><h2>最终审核结论</h2>${badge(r)}</div><p>核实总分 <b class="score-num">${r.verified.toFixed(1)}</b> / 100</p>${r.reasons.map(t=>`<p class="explain">${esc(t)}</p>`).join('')}<div class="field"><label for="approver">审批人姓名</label><input id="approver" placeholder="采购负责人 / 授权审批人"></div><div class="field"><label for="conditions">审批意见 / 整改事项、截止日与采购限额</label><textarea id="conditions" placeholder="有条件准入时必须明确整改内容、责任人、期限和限额"></textarea></div><button class="btn primary" id="approve" ${!['建议准入','有条件准入'].includes(r.decision)?'disabled':''}>记录准入审批</button>${s.approval?`<div class="callout good" style="margin-top:20px">已记录：${esc(s.approval.approver)} · ${esc(s.approval.decision)}<br>${esc(s.approval.conditions)}<br><small>${s.approval.time} · ${s.approval.version}</small></div>`:''}<p class="hint">本地审批为演示记录，不会写入 ERP，也没有强制的职责分离。</p><div class="review-panel"><h3>已确认的红线</h3><label for="redline">仅记录已核实的事实；疑似问题先澄清</label><input id="redline" value="${esc(s.redline)}" placeholder="伪造资料 / 严重安全不符合 / 关键规格不符合等"><div class="actions" style="margin-top:12px"><button class="btn small" id="redline-save">保存红线</button></div></div></section><section class="card"><div class="section-top"><h2>审核事件记录</h2><button class="btn small" id="audit-check">核验日志链</button></div><p class="hint">事件摘要引用上一事件摘要。当前浏览器日志可被本地修改，生产需服务端不可变存储和时间戳。</p>${s.log.length?s.log.slice().reverse().map(e=>`<div class="audit-event"><p><b>${esc(e.action)}</b></p><small>${new Date(e.time).toLocaleString('zh-CN')} · ${e.actor}</small><p class="hint">${esc(e.detail)}</p><div class="hash">${e.hash}</div></div>`).join(''):'<div class="empty">尚无审核事件。保存申报、签署或上传文件后记录会出现在这里。</div>'}</section></div>`;}
function render(){if(!pages[page])page='overview';$('#nav').innerHTML=Object.entries(pages).map(([k,v])=>`<a href="#${k}" class="${page===k?'active':''}"><span>${v[0]}</span>${v[1]}</a>`).join('');$('#crumb').textContent=pages[page][1];$('#policy-label').textContent=db.policy.version;$('#main').innerHTML=({overview,supplier:supplierView,evidence:evidenceView,scores:scoresView,clarify:clarifyView,policy:policyView,audit:auditView})[page]();bind();}
function download(data,name,type='application/json'){let u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function saveSupplier(redraw=true){let s=supplier();document.querySelectorAll('[data-field]').forEach(e=>s[e.dataset.field]=e.value.trim());let error='';document.querySelectorAll('[data-metric]').forEach(e=>{let v=e.value===''?null:Number(e.value);let id=e.dataset.metric;let i=dims.flatMap(d=>d.items).find(i=>i[0]===id);if(v!==null&&(!Number.isFinite(v)||v<0||(i[3]==='%'&&v>100)||(i[3]==='/4'&&(v>4||!Number.isInteger(v)))||(id==='cash'&&(v>3||!Number.isInteger(v)))))error='指标值超出有效范围。';s.metrics[id]=v;});document.querySelectorAll('[data-annual]').forEach(e=>s.annual[Number(e.dataset.year)][e.dataset.annual]=Number(e.value));if(s.annual.some(a=>a.cl<=0||a.assets<=0||a.ca<0||!Number.isInteger(a.year))||new Set(s.annual.map(a=>a.year)).size!==3)error='请填写三个不同财年，流动负债及总资产须大于零。';if(error){toast(error);return false;}s.metrics.current=Math.min(...s.annual.map(a=>a.ca/a.cl));s.metrics.equity=Math.min(...s.annual.map(a=>a.equity/a.assets*100));s.metrics.cash=s.annual.filter(a=>a.ocf>0).length;invalidate();await log('保存供应商申报','三年财务指标已重算，原签名和审批须重新确认');if(redraw){render();toast('申报已保存；请上传证据并签署。');}return true;}
function bind(){const on=(id,fn)=>{let el=$('#'+id);if(el)el.onclick=fn;};$('#selected')?.addEventListener('change',e=>{db.selected=e.target.value;persist();render();});document.querySelectorAll('[data-open],[data-select]').forEach(el=>el.onclick=()=>{db.selected=el.dataset.open||el.dataset.select;persist();location.hash='scores';if(page==='scores')render();});on('new',async()=>{let s=example('SG-'+Date.now().toString().slice(-6),'新供应商','待填写',Array(18).fill(null));s.name='';s.annual=[2023,2024,2025].map(year=>({year,ca:0,cl:0,equity:0,assets:0,ocf:0}));db.suppliers.push(s);db.selected=s.id;persist();location.hash='supplier';});on('save',saveSupplier);document.querySelectorAll('[data-field],[data-metric],[data-annual]').forEach(e=>e.addEventListener('input',()=>{supplier().signatureValid=false;supplier().approval=null;persist();}));on('sign',async()=>{if(!$('#consent')?.checked)return toast('请勾选声明确认。');if(await saveSupplier(false))await sign();});on('verify',verify);on('print',()=>window.print());on('export',()=>{let s=supplier();download(JSON.stringify({exportedAt:new Date().toISOString(),prototype:true,policy:db.policy,result:score(s,db.policy),supplier:s,attachmentNote:'文件元数据和摘要；附件原件需在证据页单独下载。'},null,2),`SourceGate-${s.id}-review.json`);});
on('upload',async()=>{let f=$('#file').files[0];if(!f)return toast('请选择文件。');if(f.size>15*1024*1024)return toast('文件须小于 15 MB。');try{let s=supplier(),e={id:crypto.randomUUID(),name:f.name,size:f.size,dimension:$('#filedim').value,hash:await digest(await f.arrayBuffer()),time:new Date().toISOString(),state:'pending'};await putFile(e.id,f);s.evidence.push(e);invalidate();await log('添加证据',`${e.name} / ${e.hash}`);render();toast('附件已保存并生成摘要；请核实资料真实性。');}catch{toast('保存失败，浏览器存储可能已满。');}});
on('authorize',async()=>{let note=$('#authnote').value.trim();if(note.length<8)return toast('请记录核验人、身份及授权依据。');let s=supplier();s.authorized=true;s.authnote=note;s.approval=null;await log('人工确认签署身份与授权',note);render();});
document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{let e=supplier().evidence.find(e=>e.id===b.dataset.review),state=$('#state-'+e.id).value,reviewer=$('#reviewer-'+e.id).value.trim(),method=$('#method-'+e.id).value.trim();if(state!=='pending'&&(!reviewer||method.length<8))return toast('请填写审核人及明确的核验依据。');Object.assign(e,{state,reviewer,method,reviewedAt:new Date().toISOString()});supplier().approval=null;await log('更新证据核验',`${e.name}：${state}；${reviewer}；${method}`);render();});
document.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{let e=supplier().evidence.find(e=>e.id===b.dataset.download),f=await getFile(e.id);if(!f)return toast('原件已不在当前浏览器中，请重新上传。');download(f,e.name,f.type);});document.querySelectorAll('[data-hashcheck]').forEach(b=>b.onclick=async()=>{let e=supplier().evidence.find(e=>e.id===b.dataset.hashcheck),f=await getFile(e.id);if(!f)return toast('无法找到当前浏览器中的原件。');let ok=await digest(await f.arrayBuffer())===e.hash;await log('附件完整性复核',`${e.name}：${ok?'摘要匹配':'摘要不匹配'}`);if(!ok){e.state='pending';supplier().approval=null;persist();}toast(ok?'摘要匹配；不代表文件内容真实。':'摘要不匹配，已退回待核验。');});
on('add-clarify',async()=>{let q=$('#question').value.trim(),due=$('#due').value;if(q.length<8||!due)return toast('请填写具体问题和截止日。');let s=supplier();s.clarifications.push({id:'C-'+String(Date.now()).slice(-6),dimension:$('#cdim').value,question:q,due,response:'',status:'open'});s.approval=null;await log('提出澄清',q);render();});on('auto-clarify',async()=>{let s=supplier(),n=0;dims.forEach(d=>{if(!s.evidence.some(e=>e.dimension===d.id&&e.state==='verified')&&!s.clarifications.some(c=>c.dimension===d.id&&c.status!=='closed')){s.clarifications.push({id:'C-'+crypto.randomUUID().slice(0,8),dimension:d.id,question:`请补充${d.name}完整证据包，并说明指标统计口径及出处。`,due:new Date(Date.now()+7*86400000).toISOString().slice(0,10),response:'',status:'open'});n++;}});s.approval=null;await log('运行规则检查',`新增 ${n} 项澄清`);render();toast(`生成 ${n} 项澄清。`);});
for(let [attr,fn] of [['answer',async c=>{let text=$('#response-'+c.id).value.trim();if(text.length<8)return toast('请填写具体的回复内容。');c.response=text;c.status='answered';await log('供应商回复澄清',c.id);render();}],['close',async c=>{c.status='closed';c.resolution='本地演示审核人确认：回复已复核；证据须另行核实。';await log('审核关闭澄清',c.id);render();}],['reopen',async c=>{c.status='open';supplier().approval=null;await log('重新打开澄清',c.id);render();}]])document.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>fn(supplier().clarifications.find(c=>c.id===b.dataset[attr])));
on('save-policy',async()=>{let next=JSON.parse(JSON.stringify(db.policy));next.company=$('#company').value.trim();next.weights=dims.map((_,n)=>Number($('#weight-'+n).value));next.floors=dims.map((_,n)=>Number($('#floor-'+n).value));next.admit=Number($('#admit').value);next.conditional=Number($('#conditional').value);document.querySelectorAll('[data-threshold]').forEach(e=>next.criteria[e.dataset.threshold][e.dataset.index]=Number(e.value));if(!SourceGate.valid(next))return toast('规则无效：请检查权重合计100%、基准0–100及分档严格递增。');next.version='CAPEX-'+new Date().toISOString();db.policy=next;db.suppliers.forEach(s=>{s.signatureValid=false;s.approval=null;});await log('评分规则更新',next.version);render();toast('新规则已保存；所有申请须按新版本重新签署。');});on('redline-save',async()=>{let s=supplier();s.redline=$('#redline').value.trim();s.approval=null;await log('更新已确认红线',s.redline||'无已确认红线');render();});on('approve',async()=>{let r=score(supplier(),db.policy),approver=$('#approver').value.trim(),conditions=$('#conditions').value.trim();if(!['建议准入','有条件准入'].includes(r.decision))return toast('当前条件不允许准入审批。');if(!approver||conditions.length<8)return toast('请记录审批人及审批意见；有条件准入须写明整改、期限和限额。');supplier().approval={approver,conditions,time:new Date().toISOString(),decision:r.decision,score:r.verified,version:db.policy.version};await log('记录准入审批',`${approver}；${r.decision}；${conditions}`);render();});on('audit-check',async()=>{let prev='GENESIS',ok=true;for(let e of supplier().log){let {hash,...body}=e;if(e.previous!==prev||await digest(JSON.stringify(body))!==hash){ok=false;break;}prev=hash;}toast(ok?'当前日志摘要链一致；不代表外部不可篡改认证。':'日志摘要链不一致。');});}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1);render();window.scrollTo(0,0);});render();
